// 🕊️ 飞书与 NotebookLM 多源知识库前端配置接口
let currentKnowledgeConfig = {};
async function loadKnowledgeProviderInputs() {
  try {
    const res = await fetch(`${getGatewayUrl()}/api/system/config/knowledge`);
    const data = await res.json();
    if (data.success && data.config) {
      currentKnowledgeConfig = data.config;
      document.getElementById('lark-wiki-token').value = data.config.lark_wiki_token || '';
      document.getElementById('lark-folder-token').value = data.config.lark_folder_token || '';
      document.getElementById('nlm-notebook-id').value = data.config.nlm_notebook_id || '';
      document.getElementById('nlm-cookie').value = data.config.nlm_cookie || '';
    }
  } catch (e) {
    console.warn('Failed to load knowledge providers config:', e);
  }
}

async function saveLarkKbConfig() {
  const role = getCurrentRole();
  const wiki = document.getElementById('lark-wiki-token').value.trim();
  const folder = document.getElementById('lark-folder-token').value.trim();

  const config = {
    ...currentKnowledgeConfig,
    lark_wiki_token: wiki,
    lark_folder_token: folder
  };

  try {
    const res = await fetch(`${getGatewayUrl()}/api/system/config/knowledge`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${_authToken}`
      },
      body: JSON.stringify({ config })
    }).then(r => r.json());

    if (res.success) {
      alert('✅ 飞书知识库配置已成功物理保存！');
      currentKnowledgeConfig = config;

      if (wiki) {
        if (confirm('是否立即物理同步该飞书云空间 Wiki 文档至本地 FTS5 知识库？')) {
          triggerLarkWikiSync(wiki);
        }
      }
    } else {
      alert(`❌ 保存失败: ${res.error}`);
    }
  } catch (err) {
    alert('❌ 无法连接网关。');
  }
}

async function triggerLarkWikiSync(wikiToken) {
  try {
    const res = await fetch(`${getGatewayUrl()}/api/lark/wiki/sync`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${_authToken}`
      },
      body: JSON.stringify({ wiki_token: wikiToken })
    }).then(r => r.json());

    if (res.success) {
      alert(`🎉 ${res.message}`);
      loadKnowledgeList(); // 刷新 RAG 列表显示
    } else {
      alert(`❌ 同步失败: ${res.error}`);
    }
  } catch (e) {
    alert('❌ 飞书 API 连接失败，请核对网络及 AppID 配置。');
  }
}

